package cn.ping.launcher;
import android.app.*;import android.os.*;import android.view.*;import android.content.*;
public class GestureTest extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();try{MainActivity activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(700);ActivityMonitor monitor=addMonitor(HiddenAppsActivity.class.getName(),null,false);runOnMainSync(()->{long now=android.os.SystemClock.uptimeMillis();MotionEvent.PointerProperties[] props=new MotionEvent.PointerProperties[2];MotionEvent.PointerCoords[] coords=new MotionEvent.PointerCoords[2];for(int i=0;i<2;i++){props[i]=new MotionEvent.PointerProperties();props[i].id=i;props[i].toolType=MotionEvent.TOOL_TYPE_FINGER;coords[i]=new MotionEvent.PointerCoords();coords[i].x=300+i*150;coords[i].y=1300;coords[i].pressure=1;coords[i].size=1;}send(activity,now,0,1,props,coords);send(activity,now,MotionEvent.ACTION_POINTER_DOWN|(1<<8),2,props,coords);coords[0].y=900;coords[1].y=900;send(activity,now,MotionEvent.ACTION_MOVE,2,props,coords);send(activity,now,MotionEvent.ACTION_UP,1,props,coords);});Activity quick=monitor.waitForActivityWithTimeout(3000);if(quick==null)throw new AssertionError("Hidden space did not open");if(!quick.getIntent().getBooleanExtra("quick",false))throw new AssertionError("Wrong hidden-space mode");result.putString("result","PASS: two-finger swipe opens hidden quick-launch activity");finish(0,result);}catch(Throwable e){result.putString("error",e.toString());finish(1,result);}}
 void send(Activity activity,long now,int action,int count,MotionEvent.PointerProperties[] p,MotionEvent.PointerCoords[] c){MotionEvent e=MotionEvent.obtain(now,now+20,action,count,p,c,0,0,1,1,0,0,android.view.InputDevice.SOURCE_TOUCHSCREEN,0);activity.dispatchTouchEvent(e);e.recycle();}
}
